/**
 * Data FSVA (Food Security & Vulnerability Atlas) — Badan Pangan Nasional.
 *
 * Tingkat DESA (278 desa, 20 kecamatan), 4 tahun (2021-2024).
 * Digenerasi dari public/data/tabel_data_YYYY.csv via _tmp/gen_fsva.mjs.
 * Kolom mentah: Wilayah, Komposit, 6 indikator rasio, IKP, IKP Ranking.
 *
 * Enam indikator dipetakan ke Tiga Pilar Ketahanan Pangan:
 *  - Ketersediaan: Rasio Luas Lahan Pertanian, Rasio Sarana Pangan
 *  - Keterjangkauan: Rasio Penduduk Miskin Desil 1, Desa Tanpa Akses Penghubung
 *  - Pemanfaatan: Rasio RT Tanpa Air Bersih, Rasio Tenaga Kesehatan
 *
 * IKP 0-100 (makin tinggi = makin tahan). Komposit 1-6 (6 = paling tahan).
 */

export interface FsvaDesa {
  /** OBJECTID peta desa (join key terhadap peta_desa_v3.geojson). */
  objectId: number;
  /** Nama kecamatan kanonik (mis. "Purwareja Klampok"). */
  kecamatan: string;
  /** Nama desa (mis. "Desa Brengkok"). */
  desa: string;
  /** Indeks komposit 1-6 (6 = paling tahan, 1-2 = sangat rawan). */
  komposit: number;
  /** Rasio luas lahan pertanian (ketersediaan). */
  rasioLahan: number;
  /** Rasio sarana pangan (ketersediaan). */
  rasioSarana: number;
  /** Rasio penduduk miskin desil 1 (keterjangkauan). */
  rasioMiskin: number;
  /** Desa tanpa akses penghubung 0/1 (keterjangkauan). */
  tanpaAkses: number;
  /** Rasio rumah tangga tanpa air bersih (pemanfaatan). */
  tanpaAirBersih: number;
  /** Rasio tenaga kesehatan (pemanfaatan). */
  rasioNakes: number;
  /** Indeks Ketahanan Pangan 0-100. */
  ikp: number;
  /** Peringkat IKP (1 = paling tahan). */
  ikpRanking: number;
}

export const FSVA_YEARS = [2021, 2022, 2023, 2024] as const;
export type FsvaYear = (typeof FSVA_YEARS)[number];

