/** Ambil FSVA satu tahun (referensi statis). */
export const fetchFsva = async (year: FsvaYear): Promise<FsvaDesa[]> =>
  FSVA_DATA[year];

/** Label klasifikasi dari indeks komposit (FSVA). */
export function kompositLabel(k: number): string {
  if (k <= 2) return "Sangat Rawan";
  if (k === 3) return "Rawan";
  if (k === 4) return "Agak Rawan";
  if (k === 5) return "Tahan";
  return "Sangat Tahan";
}

/** Klasifikasi prioritas FSVA (1-5) dari komposit. */
export function kompositPrioritas(k: number): number {
  if (k <= 2) return 1;
  if (k === 3) return 2;
  if (k === 4) return 3;
  if (k === 5) return 4;
  return 5;
}

/* ------------------------------------------------------------------ */
/* Indikator peta tematik level desa                                   */
/* ------------------------------------------------------------------ */

export type FsvaIndicatorKey =
  | "ikp"
  | "komposit"
  | "rasioLahan"
  | "rasioSarana"
  | "rasioMiskin"
  | "tanpaAkses"
  | "tanpaAirBersih"
  | "rasioNakes";

export interface FsvaIndicatorDef {
  key: FsvaIndicatorKey;
  /** Label panjang saat dipilih. */
  label: string;
  /** Label pendek untuk tombol pemilih. */
  short: string;
  pilar: "Indikator Utama" | "Ketersediaan" | "Keterjangkauan" | "Pemanfaatan";
  unit: string;
  /** true = nilai tinggi berarti baik (makin hijau). */
  higherIsBetter: boolean;
  /** Kategorikal (komposit / tanpaAkses) alih-alih kotinu. */
  categorical: boolean;
  format: (v: number) => string;
}

